# ================================================================
# GRAFIK GILLETTE - APPLY UPDATE PATCH
# ================================================================
# Version: 1.0
# Purpose: Apply structured patch from update_code.md to project files.
#
# Workflow:
#   1. User asks AI in chat for code changes
#   2. AI responds with structured operations
#   3. User saves response as update_code.md
#   4. Run: .\apply-update.ps1
#
# Supports operations: REPLACE, CREATE, DELETE, INSERT_AFTER, INSERT_BEFORE
# Safety: git commit backup + per-file .backup + verify + rollback on error
# ================================================================

[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8

# --- CONFIGURATION ---

$UPDATE_FILE = "update_code.md"
$BACKUP_DIR = ".update-backups"
$AUTO_GIT_COMMIT = $false  # true = auto git commit before apply (recommended)
$DRY_RUN = $false          # true = show what would happen, don't modify files

# --- COLORS ---
function Write-Success { param($msg) Write-Host "[OK] $msg" -ForegroundColor Green }
function Write-Info { param($msg) Write-Host "[INFO] $msg" -ForegroundColor Cyan }
function Write-Warn { param($msg) Write-Host "[WARN] $msg" -ForegroundColor Yellow }
function Write-Error2 { param($msg) Write-Host "[ERROR] $msg" -ForegroundColor Red }
function Write-Step { param($msg) Write-Host ""; Write-Host "=== $msg ===" -ForegroundColor Magenta }

# --- HELPER: UTF-8 file operations ---

function Read-FileUtf8 {
    param([string]$Path)
    if (-not (Test-Path $Path)) {
        throw "File not found: $Path"
    }
    return [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
}

function Write-FileUtf8 {
    param(
        [string]$Path,
        [string]$Content
    )
    $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
    $absolutePath = if ([System.IO.Path]::IsPathRooted($Path)) {
        $Path
    } else {
        Join-Path (Get-Location) $Path
    }
    # Ensure directory exists
    $dir = Split-Path $absolutePath -Parent
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    [System.IO.File]::WriteAllText($absolutePath, $Content, $utf8NoBom)
}

# --- HELPER: Git integration ---

function Get-GitStatus {
    try {
        $status = git status --porcelain 2>$null
        if ($LASTEXITCODE -ne 0) { return $null }
        return $status
    } catch {
        return $null
    }
}

function Test-GitClean {
    $status = Get-GitStatus
    if ($null -eq $status) { return $false }  # not a git repo or git not available
    return [string]::IsNullOrWhiteSpace($status)
}

function New-GitBackup {
    param([string]$Message)
    try {
        git add -A 2>&1 | Out-Null
        git commit -m $Message --allow-empty 2>&1 | Out-Null
        if ($LASTEXITCODE -eq 0) {
            $hash = (git rev-parse --short HEAD 2>$null).Trim()
            return $hash
        }
    } catch {}
    return $null
}

# --- HELPER: File backup ---

function Backup-File {
    param([string]$FilePath)

    if (-not (Test-Path $FilePath)) {
        return $null  # nothing to backup (file will be created)
    }

    $timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
    $safeName = $FilePath.Replace('\', '_').Replace('/', '_').Replace(':', '_')
    $backupPath = Join-Path $BACKUP_DIR "$safeName.$timestamp.backup"

    if (-not (Test-Path $BACKUP_DIR)) {
        New-Item -ItemType Directory -Path $BACKUP_DIR -Force | Out-Null
    }

    Copy-Item -Path $FilePath -Destination $backupPath -Force
    return $backupPath
}

# --- PARSER: update_code.md ---

function Parse-UpdateFile {
    param([string]$Content)

    $operations = @()
    $currentOp = $null
    $mode = "none"  # none, header, locate, replace, content
    $codeBlockLang = ""
    $codeBuffer = New-Object System.Text.StringBuilder
    $inCodeBlock = $false

    $lines = $Content -split "`r?`n"

    for ($i = 0; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        $trimmed = $line.Trim()

        # Detect new operation
        if ($trimmed -match '^### OP\s*(\d+)?\s*:?\s*(.*)$') {
            # Save previous operation if exists
            if ($currentOp) {
                if ($inCodeBlock) {
                    # Close pending code block
                    if ($mode -eq "locate") {
                        $currentOp.LocateBlock = $codeBuffer.ToString().TrimEnd()
                    } elseif ($mode -eq "replace") {
                        $currentOp.ReplaceBlock = $codeBuffer.ToString().TrimEnd()
                    } elseif ($mode -eq "content") {
                        $currentOp.Content = $codeBuffer.ToString().TrimEnd()
                    }
                    $inCodeBlock = $false
                }
                $operations += $currentOp
            }
            $currentOp = @{
                Number = if ($matches[1]) { [int]$matches[1] } else { $operations.Count + 1 }
                Title = $matches[2]
                File = ""
                Action = ""
                LocateBlock = ""
                ReplaceBlock = ""
                Content = ""
            }
            $codeBuffer.Clear() | Out-Null
            $inCodeBlock = $false
            $mode = "header"
            continue
        }

        if (-not $currentOp) { continue }

        # Parse headers (before code blocks)
        if (-not $inCodeBlock) {
            if ($trimmed -match '^(?:\*\*)?FILE(?:\*\*)?:\s*[`]?(.+?)[`]?$') {
                $currentOp.File = $matches[1].Trim() -replace '`', ''
                continue
            }
            if ($trimmed -match '^(?:\*\*)?ACTION(?:\*\*)?:\s*[`]?(\w+)[`]?') {
                $currentOp.Action = $matches[1].Trim().ToUpper()
                continue
            }
            if ($trimmed -match '^(?:\*\*)?LOCATE(?:\*\*)?:?\s*$') {
                $mode = "locate"
                $codeBuffer.Clear() | Out-Null
                continue
            }
            if ($trimmed -match '^(?:\*\*)?REPLACE_?WITH(?:\*\*)?:?\s*$') {
                $mode = "replace"
                $codeBuffer.Clear() | Out-Null
                continue
            }
            if ($trimmed -match '^(?:\*\*)?CONTENT(?:\*\*)?:?\s*$') {
                $mode = "content"
                $codeBuffer.Clear() | Out-Null
                continue
            }
        }

        # Handle code blocks
        if ($trimmed -match '^```(\w*)$' -and -not $inCodeBlock) {
            $inCodeBlock = $true
            $codeBlockLang = $matches[1]
            $codeBuffer.Clear() | Out-Null
            continue
        }
        if ($trimmed -match '^```$' -and $inCodeBlock) {
            $inCodeBlock = $false
            $code = $codeBuffer.ToString().TrimEnd("`r", "`n")
            if ($mode -eq "locate") {
                $currentOp.LocateBlock = $code
            } elseif ($mode -eq "replace") {
                $currentOp.ReplaceBlock = $code
            } elseif ($mode -eq "content") {
                $currentOp.Content = $code
            }
            $codeBuffer.Clear() | Out-Null
            continue
        }

        if ($inCodeBlock) {
            [void]$codeBuffer.AppendLine($line)
        }
    }

    # Save last operation
    if ($currentOp) {
        if ($inCodeBlock) {
            if ($mode -eq "locate") {
                $currentOp.LocateBlock = $codeBuffer.ToString().TrimEnd()
            } elseif ($mode -eq "replace") {
                $currentOp.ReplaceBlock = $codeBuffer.ToString().TrimEnd()
            } elseif ($mode -eq "content") {
                $currentOp.Content = $codeBuffer.ToString().TrimEnd()
            }
        }
        $operations += $currentOp
    }

    return $operations
}

# --- VALIDATOR: check operations ---

function Test-Operation {
    param($Op)

    $errors = @()

    if (-not $Op.File) {
        $errors += "Missing FILE"
    }
    if (-not $Op.Action) {
        $errors += "Missing ACTION"
    }

    switch ($Op.Action) {
        "REPLACE" {
            if (-not $Op.LocateBlock) { $errors += "REPLACE requires LOCATE block" }
            if (-not $Op.ReplaceBlock) { $errors += "REPLACE requires REPLACE_WITH block" }
        }
        "CREATE" {
            if (-not $Op.Content) { $errors += "CREATE requires CONTENT block" }
        }
        "DELETE" {
            # No additional requirements
        }
        "INSERT_AFTER" {
            if (-not $Op.LocateBlock) { $errors += "INSERT_AFTER requires LOCATE block" }
            if (-not $Op.ReplaceBlock) { $errors += "INSERT_AFTER requires REPLACE_WITH block (content to insert)" }
        }
        "INSERT_BEFORE" {
            if (-not $Op.LocateBlock) { $errors += "INSERT_BEFORE requires LOCATE block" }
            if (-not $Op.ReplaceBlock) { $errors += "INSERT_BEFORE requires REPLACE_WITH block (content to insert)" }
        }
        default {
            $errors += "Unknown ACTION: $($Op.Action) (allowed: REPLACE, CREATE, DELETE, INSERT_AFTER, INSERT_BEFORE)"
        }
    }

    return $errors
}
# --- EXECUTOR: apply single operation ---

function Invoke-Operation {
    param(
        $Op,
        [string]$BackupPath
    )

    switch ($Op.Action) {
        "REPLACE" {
            $content = Read-FileUtf8 -Path $Op.File
            # Normalize line endings for matching (handle both CRLF and LF)
            $normalized = $content -replace "`r`n", "`n"
            $locateNorm = $Op.LocateBlock -replace "`r`n", "`n"

            if ($normalized -notmatch [regex]::Escape($locateNorm)) {
                throw "LOCATE block not found in file. Check exact match (whitespace, indentation)."
            }

            # Count occurrences
            $matches = [regex]::Matches($normalized, [regex]::Escape($locateNorm))
            if ($matches.Count -gt 1) {
                throw "LOCATE block found $($matches.Count) times. Must be unique. Add more context to LOCATE."
            }

            # Replace on normalized content
            $newContent = $normalized -replace [regex]::Escape($locateNorm), $Op.ReplaceBlock.Replace('$', '$$')

            # Restore original line endings (CRLF if original had it)
            if ($content -match "`r`n") {
                $newContent = $newContent -replace "`n", "`r`n"
            }

            Write-FileUtf8 -Path $Op.File -Content $newContent

            $addedLines = ($Op.ReplaceBlock -split "`n").Count
            $removedLines = ($Op.LocateBlock -split "`n").Count
            return "Replaced $removedLines lines with $addedLines lines"
        }

        "CREATE" {
            if (Test-Path $Op.File) {
                throw "File already exists. Use REPLACE or DELETE first."
            }
            Write-FileUtf8 -Path $Op.File -Content $Op.Content
            $lines = ($Op.Content -split "`n").Count
            return "Created file with $lines lines"
        }

        "DELETE" {
            if (-not (Test-Path $Op.File)) {
                throw "File not found: $($Op.File)"
            }
            # Try git rm first (if tracked)
            try {
                git ls-files --error-unmatch $Op.File 2>&1 | Out-Null
                if ($LASTEXITCODE -eq 0) {
                    git rm $Op.File 2>&1 | Out-Null
                    return "Deleted (git rm)"
                }
            } catch {}
            # Fallback: regular delete
            Remove-Item -Path $Op.File -Force
            return "Deleted (not git-tracked)"
        }

        "INSERT_AFTER" {
            $content = Read-FileUtf8 -Path $Op.File
            $normalized = $content -replace "`r`n", "`n"
            $locateNorm = $Op.LocateBlock -replace "`r`n", "`n"

            if ($normalized -notmatch [regex]::Escape($locateNorm)) {
                throw "LOCATE block not found in file"
            }

            $insertContent = "`n" + $Op.ReplaceBlock
            $newContent = $normalized -replace [regex]::Escape($locateNorm), ($locateNorm + $insertContent).Replace('$', '$$')

            if ($content -match "`r`n") {
                $newContent = $newContent -replace "`n", "`r`n"
            }

            Write-FileUtf8 -Path $Op.File -Content $newContent
            $addedLines = ($Op.ReplaceBlock -split "`n").Count
            return "Inserted $addedLines lines after LOCATE block"
        }

        "INSERT_BEFORE" {
            $content = Read-FileUtf8 -Path $Op.File
            $normalized = $content -replace "`r`n", "`n"
            $locateNorm = $Op.LocateBlock -replace "`r`n", "`n"

            if ($normalized -notmatch [regex]::Escape($locateNorm)) {
                throw "LOCATE block not found in file"
            }

            $insertContent = $Op.ReplaceBlock + "`n"
            $newContent = $normalized -replace [regex]::Escape($locateNorm), ($insertContent + $locateNorm).Replace('$', '$$')

            if ($content -match "`r`n") {
                $newContent = $newContent -replace "`n", "`r`n"
            }

            Write-FileUtf8 -Path $Op.File -Content $newContent
            $addedLines = ($Op.ReplaceBlock -split "`n").Count
            return "Inserted $addedLines lines before LOCATE block"
        }

        default {
            throw "Unknown action: $($Op.Action)"
        }
    }
}

# --- ROLLBACK ---

function Restore-Backups {
    param($Backups)

    Write-Warn "Rolling back all changes..."
    foreach ($backup in $Backups) {
        if ($backup.BackupPath -and (Test-Path $backup.BackupPath)) {
            Copy-Item -Path $backup.BackupPath -Destination $backup.FilePath -Force
            Write-Info "  Restored: $($backup.FilePath)"
        } elseif ($backup.WasCreated) {
            if (Test-Path $backup.FilePath) {
                Remove-Item -Path $backup.FilePath -Force
                Write-Info "  Removed created file: $($backup.FilePath)"
            }
        }
    }
}

# --- MAIN EXECUTION ---

Write-Host "================================================" -ForegroundColor Cyan
Write-Host " GRAFIK GILLETTE - Apply Update Patch" -ForegroundColor Cyan
Write-Host "================================================" -ForegroundColor Cyan
Write-Host ""

# Check working directory
if (-not (Test-Path "index.html")) {
    Write-Error2 "index.html not found. Run from project root!"
    exit 1
}

# Check update file
if (-not (Test-Path $UPDATE_FILE)) {
    Write-Error2 "$UPDATE_FILE not found in current directory."
    Write-Info "Create this file with patch content from AI chat."
    exit 1
}

# Check git status
if ($AUTO_GIT_COMMIT) {
    Write-Step "Checking git status"
    if (-not (Test-GitClean)) {
        Write-Warn "Working tree has uncommitted changes."
        $answer = Read-Host "Commit them before applying patch? (y/N)"
        if ($answer -eq 'y') {
            $backupHash = New-GitBackup -Message "chore: pre-patch backup"
            if ($backupHash) {
                Write-Success "Git backup created: $backupHash"
            } else {
                Write-Warn "Git backup failed, continuing without git safety net"
            }
        }
    } else {
        Write-Success "Working tree clean"
    }
}

# Parse update file
Write-Step "Parsing $UPDATE_FILE"
$content = Read-FileUtf8 -Path $UPDATE_FILE
$operations = Parse-UpdateFile -Content $content

if ($operations.Count -eq 0) {
    Write-Error2 "No operations found in $UPDATE_FILE"
    Write-Info "Expected format: '### OP N: title' followed by FILE, ACTION, LOCATE/REPLACE_WITH/CONTENT blocks"
    exit 1
}

Write-Success "Found $($operations.Count) operation(s)"

# Validate all operations first
Write-Step "Validating operations"
$hasErrors = $false
foreach ($op in $operations) {
    $errors = Test-Operation -Op $op
    if ($errors.Count -gt 0) {
        Write-Error2 "OP $($op.Number) [$($op.Title)]:"
        foreach ($err in $errors) {
            Write-Host "    - $err" -ForegroundColor Red
        }
        $hasErrors = $true
    } else {
        Write-Success "OP $($op.Number) [$($op.Title)] - $($op.Action) $($op.File)"
    }
}

if ($hasErrors) {
    Write-Error2 "Validation failed. Fix errors above and retry."
    exit 1
}

# Dry run mode
if ($DRY_RUN) {
    Write-Warn "DRY_RUN mode enabled. No files will be modified."
    Write-Info "Set `$DRY_RUN = `$false in script to actually apply changes."
    exit 0
}

# Confirm before applying
Write-Host ""
Write-Warn "About to apply $($operations.Count) operation(s)."
$confirm = Read-Host "Continue? (y/N)"
if ($confirm -ne 'y') {
    Write-Info "Aborted by user."
    exit 0
}

# Apply operations
Write-Step "Applying operations"
$backups = @()
$succeeded = 0
$failed = 0

foreach ($op in $operations) {
    Write-Host ""
    Write-Info "OP $($op.Number): $($op.Action) $($op.File)"

    # Backup
    $wasCreated = -not (Test-Path $op.File)
    $backupPath = if ($op.Action -ne "CREATE") { Backup-File -FilePath $op.File } else { $null }
    $backups += @{
        FilePath = $op.File
        BackupPath = $backupPath
        WasCreated = $wasCreated
    }

    if ($backupPath) {
        Write-Host "    Backup: $backupPath" -ForegroundColor DarkGray
    }

    # Execute
    try {
        $result = Invoke-Operation -Op $op -BackupPath $backupPath
        Write-Success "    $result"
        $succeeded++
    } catch {
        Write-Error2 "    Failed: $($_.Exception.Message)"
        $failed++

        Write-Host ""
        Write-Warn "Rollback all changes? (y/N)"
        $rollback = Read-Host
        if ($rollback -eq 'y') {
            Restore-Backups -Backups $backups
            Write-Error2 "All changes rolled back. Exiting."
            exit 1
        } else {
            Write-Warn "Continuing with remaining operations..."
        }
    }
}

# Summary
Write-Step "Summary"
Write-Host "Succeeded: $succeeded / $($operations.Count)" -ForegroundColor Green
if ($failed -gt 0) {
    Write-Host "Failed: $failed" -ForegroundColor Red
}
Write-Host "Backups in: $BACKUP_DIR/" -ForegroundColor Gray

# Next steps
Write-Host ""
Write-Host "Next steps:" -ForegroundColor Cyan
Write-Host "  1. Verify changes: git status" -ForegroundColor Gray
Write-Host "  2. Review diff: git diff" -ForegroundColor Gray
Write-Host "  3. Test in browser (F12, hard reload)" -ForegroundColor Gray
Write-Host "  4. Commit: git commit -am 'apply: <description>'" -ForegroundColor Gray
Write-Host "  5. Cleanup old backups (optional): Remove-Item $BACKUP_DIR -Recurse" -ForegroundColor Gray
Write-Host ""
Write-Host "Rollback single file:" -ForegroundColor Yellow
Write-Host "  git checkout HEAD -- <path>" -ForegroundColor Gray
Write-Host "OR restore from backup:" -ForegroundColor Yellow
Write-Host "  Copy-Item $BACKUP_DIR/<file>.backup <original-path>" -ForegroundColor Gray
Write-Host ""

# ================================================================
# GRAFIK GILLETTE - EXPORT PROJECT TO code.json
# ================================================================
# Version: 3.0 - JSON output (bypasses Anthropic MIME sniffing)
# Purpose: Bundle project as JSON for chat upload
#
#   1. Run: .\export-code.ps1
#   
# Anthropic detects file type by CONTENT, not extension.
# JSON format guarantees MIME "application/json" - always allowed.
# ================================================================

[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8

# --- CONFIGURATION ---

$OUTPUT_FILE = "code.json"
$MAX_FILE_SIZE_KB = 500
$MAX_TOTAL_SIZE_KB = 2048

$INCLUDE_EXTENSIONS = @(
    '.html', '.js', '.css', '.json',
    '.md', '.ps1', '.yml', '.yaml',
    '.txt'
)

$EXCLUDE_PATTERNS = @(
    '\.git',
    'node_modules',
    '\.venv',
    'venv',
    'screenshots',
    'icons',
    'tools',
    '\.vscode',
    '__pycache__',
    '\.pytest_cache'
)

$EXCLUDE_FILES = @(
    'code.md',
    'code.txt',
    'code.json',
    'update_code.md',
    'update_code.txt',
    'update_code.json',
    'HANDOFF.md',
    'package-lock.json',
    'yarn.lock',
    '.env',
    '.DS_Store',
    'Thumbs.db'
)

$EXCLUDE_FILE_PATTERNS = @(
    'mockup-*.html',
    '*.min.js',
    '*.min.css',
    '*.backup',
    '*.log',
    '*.tmp'
)

# --- HELPER FUNCTIONS ---

function Get-LanguageHint {
    param([string]$Extension)
    switch ($Extension) {
        '.js'   { 'javascript' }
        '.html' { 'html' }
        '.css'  { 'css' }
        '.json' { 'json' }
        '.md'   { 'markdown' }
        '.ps1'  { 'powershell' }
        '.yml'  { 'yaml' }
        '.yaml' { 'yaml' }
        default { 'text' }
    }
}

function Should-ExcludeFile {
    param([string]$FilePath, [string]$FileName)
    foreach ($pattern in $EXCLUDE_PATTERNS) {
        if ($FilePath -match $pattern) { return $true }
    }
    if ($EXCLUDE_FILES -contains $FileName) { return $true }
    foreach ($pattern in $EXCLUDE_FILE_PATTERNS) {
        if ($FileName -like $pattern) { return $true }
    }
    return $false
}

function Get-GitInfo {
    $info = @{ Commit = "unknown"; Branch = "unknown"; Status = "unknown" }
    try {
        $commit = git rev-parse --short HEAD 2>$null
        if ($LASTEXITCODE -eq 0) { $info.Commit = $commit.Trim() }
    } catch {}
    try {
        $branch = git branch --show-current 2>$null
        if ($LASTEXITCODE -eq 0) { $info.Branch = $branch.Trim() }
    } catch {}
    try {
        $status = git status --porcelain 2>$null
        if ($LASTEXITCODE -eq 0) {
            if ([string]::IsNullOrWhiteSpace($status)) { $info.Status = "clean" }
            else {
                $modifiedCount = ($status -split "`n" | Where-Object { $_.Trim() }).Count
                $info.Status = "$modifiedCount uncommitted change(s)"
            }
        }
    } catch {}
    return $info
}

function Format-FileSize {
    param([long]$Bytes)
    if ($Bytes -lt 1024) { return "$Bytes B" }
    if ($Bytes -lt 1048576) { return "{0:N1} KB" -f ($Bytes / 1024) }
    return "{0:N2} MB" -f ($Bytes / 1048576)
}

function Get-ProjectTree {
    param([string]$RootPath, [int]$MaxDepth = 4)
    $script:tree = @()
    $script:tree += "Graffik/"

    function Add-TreeLevel {
        param([string]$Path, [string]$Prefix, [int]$CurrentDepth, [int]$MaxDepth)
        if ($CurrentDepth -ge $MaxDepth) { return }
        $items = Get-ChildItem -Path $Path -Force | Sort-Object { $_.PSIsContainer -eq $false }, Name
        $items = $items | Where-Object {
            $itemPath = $_.FullName.Replace('\', '/')
            -not (Should-ExcludeFile -FilePath $itemPath -FileName $_.Name)
        }
        $count = $items.Count
        for ($i = 0; $i -lt $count; $i++) {
            $item = $items[$i]
            $isLast = ($i -eq $count - 1)
            $marker = if ($isLast) { "\--- " } else { "+--- " }
            $extension = if ($item.PSIsContainer) { "/" } else { "" }
            $line = "$Prefix$marker$($item.Name)$extension"
            $script:tree += $line
            if ($item.PSIsContainer) {
                $newPrefix = if ($isLast) { "$Prefix     " } else { "$Prefix|    " }
                Add-TreeLevel -Path $item.FullName -Prefix $newPrefix -CurrentDepth ($CurrentDepth + 1) -MaxDepth $MaxDepth
            }
        }
    }

    Add-TreeLevel -Path $RootPath -Prefix "" -CurrentDepth 0 -MaxDepth $MaxDepth
    return ($script:tree -join "`n")
}

# --- MAIN EXECUTION ---

Write-Host "================================================" -ForegroundColor Cyan
Write-Host " GRAFIK GILLETTE - Export to $OUTPUT_FILE (JSON)" -ForegroundColor Cyan
Write-Host "================================================" -ForegroundColor Cyan
Write-Host ""

if (-not (Test-Path "index.html")) {
    Write-Host "[ERROR] index.html not found. Run from project root!" -ForegroundColor Red
    exit 1
}

$projectRoot = Get-Location
Write-Host "[INFO] Project root: $projectRoot" -ForegroundColor Gray

$gitInfo = Get-GitInfo
Write-Host "[INFO] Git: $($gitInfo.Branch) | $($gitInfo.Commit) | $($gitInfo.Status)" -ForegroundColor Gray

Write-Host ""
Write-Host "[SCAN] Scanning project files..." -ForegroundColor Yellow

$allFiles = Get-ChildItem -Path $projectRoot -Recurse -File -Force | Where-Object {
    $ext = $_.Extension.ToLower()
    $INCLUDE_EXTENSIONS -contains $ext
}

$includedFiles = @()
$excludedCount = 0

foreach ($file in $allFiles) {
    $relativePath = $file.FullName.Substring($projectRoot.Path.Length + 1).Replace('\', '/')
    if (Should-ExcludeFile -FilePath $relativePath -FileName $file.Name) {
        $excludedCount++
        continue
    }
    $includedFiles += $file
}

$includedFiles = $includedFiles | Sort-Object {
    $rel = $_.FullName.Substring($projectRoot.Path.Length + 1)
    $depth = ($rel -split '[\\/]').Count
    "{0:D3}_{1}" -f $depth, $rel
}

Write-Host "[SCAN] Found $($allFiles.Count) files, included $($includedFiles.Count), excluded $excludedCount" -ForegroundColor Gray

$totalSize = ($includedFiles | Measure-Object -Property Length -Sum).Sum
Write-Host "[SIZE] Total content: $(Format-FileSize $totalSize)" -ForegroundColor Gray

Write-Host ""
Write-Host "[TREE] Building structure tree..." -ForegroundColor Yellow
$treeString = Get-ProjectTree -RootPath $projectRoot -MaxDepth 4

Write-Host "[BUILD] Building JSON structure..." -ForegroundColor Yellow

# Build files array
$filesArray = @()
$fileIndex = 0
$largeFiles = @()

foreach ($file in $includedFiles) {
    $fileIndex++
    $relativePath = $file.FullName.Substring($projectRoot.Path.Length + 1).Replace('\', '/')
    $sizeKB = [math]::Round($file.Length / 1024, 1)

    if ($sizeKB -gt $MAX_FILE_SIZE_KB) {
        $largeFiles += "$relativePath ($sizeKB KB)"
    }

    try {
        $fileContent = [System.IO.File]::ReadAllText($file.FullName, [System.Text.Encoding]::UTF8)
        $lineCount = ($fileContent -split "`n").Count
    } catch {
        Write-Host "[WARN] Failed to read: $relativePath" -ForegroundColor Yellow
        continue
    }

    $langHint = Get-LanguageHint -Extension $file.Extension.ToLower()

    if ($fileIndex % 5 -eq 0 -or $fileIndex -eq $includedFiles.Count) {
        Write-Host "  [$fileIndex/$($includedFiles.Count)] $relativePath" -ForegroundColor DarkGray
    }

    $filesArray += [ordered]@{
        path = $relativePath
        language = $langHint
        size_bytes = $file.Length
        size_readable = Format-FileSize $file.Length
        lines = $lineCount
        content = $fileContent
    }
}

# Build root JSON object
$jsonObject = [ordered]@{
    project = "Grafik Gillette"
    description = "PWA for shift schedule management (4 brigades, P and G factory)"
    generated = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    git = [ordered]@{
        branch = $gitInfo.Branch
        commit = $gitInfo.Commit
        status = $gitInfo.Status
    }
    stats = [ordered]@{
        files_included = $includedFiles.Count
        files_excluded = $excludedCount
        total_size_bytes = $totalSize
        total_size_readable = Format-FileSize $totalSize
    }
    ai_instructions = @(
        "Read AGENT.md first if included - it contains critical project rules"
        "Do not suggest ES module imports or exports (project uses classic scripts)"
        "Preserve UTF-8 characters literally (Polish and Ukrainian text)"
        "Consider all three cell skins when suggesting visual changes"
        "Use LOCATE + REPLACE blocks for any code modifications"
        "Verify file paths against project structure before proposing changes"
    )
    project_structure = $treeString
    large_files = $largeFiles
    files = $filesArray
}

Write-Host "[CONVERT] Converting to JSON..." -ForegroundColor Yellow

# Convert to JSON with proper depth (files array is nested)
$jsonString = $jsonObject | ConvertTo-Json -Depth 10 -Compress:$false

# Write UTF-8 without BOM
Write-Host "[SAVE] Writing to $OUTPUT_FILE..." -ForegroundColor Yellow

$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText(
    (Join-Path $projectRoot $OUTPUT_FILE),
    $jsonString,
    $utf8NoBom
)

$outputSize = (Get-Item (Join-Path $projectRoot $OUTPUT_FILE)).Length

Write-Host ""
Write-Host "================================================" -ForegroundColor Green
Write-Host " EXPORT COMPLETE" -ForegroundColor Green
Write-Host "================================================" -ForegroundColor Green
Write-Host "Output: $OUTPUT_FILE ($(Format-FileSize $outputSize))" -ForegroundColor White
Write-Host "Files: $($includedFiles.Count)" -ForegroundColor White
Write-Host "MIME type: application/json (allowed by chat)" -ForegroundColor Green

if ($outputSize -gt 10485760) {
    Write-Host ""
    Write-Host "[WARN] File exceeds 10 MB!" -ForegroundColor Red
} elseif ($outputSize -gt 5242880) {
    Write-Host ""
    Write-Host "[INFO] File is large ($(Format-FileSize $outputSize))" -ForegroundColor Yellow
}

Write-Host ""
Write-Host "Next steps:" -ForegroundColor Cyan
Write-Host "  1. Upload $OUTPUT_FILE to chat (JSON allowed!)" -ForegroundColor Gray
Write-Host "  2. AI reads .files array with .path and .content" -ForegroundColor Gray
Write-Host "  3. Save AI response as update_code.md" -ForegroundColor Gray
Write-Host "  4. Run: .\apply-update.ps1" -ForegroundColor Gray
Write-Host ""

/* ================================================================
   GRAFIK GILLETTE — Service Worker (PWA)
   Cache'owanie + powiadomienia push o zmianach
   ================================================================ */
const CACHE_NAME = 'grafik-gillette-v20260821cleanup';
const ASSETS = [
  './',
  './index.html',
  './manifest.json',
  './css/calendar.css',
  './css/components.css',
  './css/dashboard.css',
  './css/layout.css',
  './css/overtime.css',
  './css/print.css',
  './css/responsive.css',
  './css/smart-popup.css',
  './css/variables.css',
  './css/views.css',
  './js/schedules/_core.js',
  './js/schedules/_registry.js',
  './js/schedules/gillette/metadata.js',
  './js/schedules/gillette/2026.js',
  './js/personal/sync-tracking.js',
  './js/overtime-logic.js',
  './js/core.js',
  './js/ui.js',
  './js/edit.js',
  './js/dashboard.js',
  './js/calendar.js',
  './js/views.js',
  './js/actions.js',
  './js/pwa.js',
  './js/sync.js',
  './js/admin.js',
  './js/i18n/pl.js',
  './js/i18n/en.js',
  './js/i18n/uk.js',
  './js/i18n/i18n.js',
  './js/personalization.js',
  './js/main.js',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-512-maskable.png',
];

/* === INSTALL: cache'ujemy wszystkie zasoby === */
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(ASSETS))
      .then(() => self.skipWaiting())
  );
});

/* === ACTIVATE: usuwamy stare cache === */
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key)))
      )
      .then(() => self.clients.claim())
  );
});

/* === FETCH: network first, then cache (stale-while-revalidate) === */
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  // Ignore requests from browser extensions (chrome-extension://, moz-extension://, etc.)
  const url = new URL(event.request.url);
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return;

  event.respondWith(
    caches.match(event.request).then((cached) => {
      const fetchPromise = fetch(event.request)
        .then((response) => {
          if (response && response.status === 200 && response.type === 'basic') {
            const clone = response.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(event.request, clone));
          }
          return response;
        })
        .catch(() => cached);
      return cached || fetchPromise;
    })
  );
});

/* === PUSH: pokazujemy powiadomienia === */
self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch (e) {
    data = { title: 'Grafik Gillette', body: 'Nadchodzi zmiana!' };
  }
  const options = {
    body: data.body || 'Sprawdź grafik swojej brygady',
    icon: './icons/icon-192.png',
    badge: './icons/icon-192.png',
    vibrate: [200, 100, 200],
    data: { url: data.url || './' },
    tag: 'grafik-reminder',
  };
  event.waitUntil(self.registration.showNotification(data.title || '⏰ Grafik Gillette', options));
});

/* === NOTIFICATION CLICK: open the app === */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url =
    event.notification.data && event.notification.data.url ? event.notification.data.url : './';
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ('focus' in client) {
          client.navigate(url);
          return client.focus();
        }
      }
      if (clients.openWindow) return clients.openWindow(url);
    })
  );
});
/* === MESSAGE: handling commands from the client === */
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

