  cursor: pointer;
  padding: 4px 14px;
  user-select: none;
  border-radius: 10px;
  transition: all 0.15s;
}
.month-nav button:hover {
  background: var(--text-header);
  color: #fff;
  transform: scale(1.05);
}
.month-title {
  font-size: 22px;
  color: var(--text-header);
  font-weight: 700;
  min-width: 0;
  flex: 1 1 auto;
  text-align: center;
}
.month-hours {
