  background: var(--bg-cell);
  border: 1px solid var(--border-cell);
  border-radius: 8px;
  animation: fadeInUp 0.3s ease-out;
}

.notif-lead-label {
  font-size: 11px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
  font-weight: 700;
}

.notif-lead-btns {
  display: flex;
  gap: 6px;
}

.notif-lead-btn {
  flex: 1;
  padding: 8px 12px;
  border: 2px solid var(--border-cell);
  background: var(--bg-container);
  color: var(--text-main);
  border-radius: 6px;
  cursor: pointer;
  font-weight: 700;
  font-size: 13px;
  transition: all 0.15s;
}

.notif-lead-btn:hover {
  border-color: var(--text-header);
