}





/* Pozwól kalendarzowi miesięcznemu przewijać się na małych/mobilnych ekranach (naprawia miesiące potrzebujące 6 wierszy, np. sierpień) */


/* Poprawka dla niskich wysokości viewportu (telefony w poziomie, małe okna): pozwól kalendarzowi przewijać się
   w pionie, aby miesiące potrzebujące 6 wierszy (np. sierpień) nie ucinały ostatniego tygodnia. */




/* === INFO PANEL SECTIONS === */
.info-section {
  margin-bottom: 12px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-cell);
}
.info-section:last-child {
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: none;
}
.info-section-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-header);
  margin-bottom: 6px;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* Stable cell layout: date top-left, marker bottom-center */
.day-cell:not(.empty) {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: stretch;
}
.day-cell .day-num {
  align-self: flex-start;
  margin: 0;
  padding: 0;
}
.day-cell .day-shift {
  align-self: center;
  margin-top: auto;
  margin-bottom: 6px; /* room above color strip */
  min-height: 1.2em;
}
.day-cell .ot-badge,
.day-cell .ot-marker {
  position: absolute;
  top: 4px;
  right: 4px;
  z-index: 3;
}

.day-cell .day-note {
  position: absolute;
  top: 4px;
  right: 22px; /* left of ot-marker when both present */
  z-index: 3;
  font-size: 12px;
  line-height: 1;
  pointer-events: none;
}
.day-cell.has-ot .day-note {
  right: 22px;
}


/* ===== CELL SKINS (body.skin-*) ===== */

/* --- strip: neutral body + left color bar; vacation also calm (strip + light tint) --- */
body.skin-strip .day-cell.cell-R,
body.skin-strip .day-cell.cell-P,
body.skin-strip .day-cell.cell-N {
  background: var(--bg-cell);
  color: var(--text-main);
  border-color: var(--border-cell);
  box-shadow: none;
}
body.skin-strip .day-cell.cell-R::before,
body.skin-strip .day-cell.cell-P::before,
body.skin-strip .day-cell.cell-N::before,
body.skin-strip .day-cell.urlop::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 4px;
  border-radius: 10px 0 0 10px;
  z-index: 1;
}
body.skin-strip .day-cell.cell-R::before { background: var(--color-R); }
body.skin-strip .day-cell.cell-P::before { background: var(--color-P); }
body.skin-strip .day-cell.cell-N::before { background: var(--color-N); }
body.skin-strip .day-cell.urlop::before { background: var(--color-U); }

body.skin-strip .day-cell.cell-R .day-shift { color: var(--color-R); text-shadow: none; }
body.skin-strip .day-cell.cell-P .day-shift { color: var(--color-P); text-shadow: none; }
body.skin-strip .day-cell.cell-N .day-shift { color: var(--color-N); text-shadow: none; }
body.skin-strip .day-cell.cell-R .day-num,
body.skin-strip .day-cell.cell-P .day-num,
body.skin-strip .day-cell.cell-N .day-num {
  color: var(--text-main);
  text-shadow: none;
}

body.skin-strip .day-cell.urlop {
  background: color-mix(in srgb, var(--color-U) 18%, var(--bg-cell)) !important;
  color: var(--text-main) !important;
  border-color: var(--border-cell) !important;
  text-shadow: none !important;
}
body.skin-strip .day-cell.urlop .day-num,
body.skin-strip .day-cell.urlop .day-shift {
  color: var(--text-main) !important;
}
body.skin-strip .day-cell.urlop::after {
  display: none !important;
}

/* --- colored outline skin: colored cell frame + date ring --- */
body.skin-quiet .day-cell.cell-R,
body.skin-quiet .day-cell.cell-P,
body.skin-quiet .day-cell.cell-N {
  background: var(--bg-cell);
  color: var(--text-main);
  box-shadow: none;
}
body.skin-quiet .day-cell.cell-R { border-color: var(--color-R); }
body.skin-quiet .day-cell.cell-P { border-color: var(--color-P); }
body.skin-quiet .day-cell.cell-N { border-color: var(--color-N); }
body.skin-quiet .day-cell.cell-R::after,
body.skin-quiet .day-cell.cell-P::after,
body.skin-quiet .day-cell.cell-N::after {
  display: none !important;
  content: none;
}
body.skin-quiet .day-cell.cell-R .day-shift,
body.skin-quiet .day-cell.cell-P .day-shift,
body.skin-quiet .day-cell.cell-N .day-shift {
  color: var(--text-main);
  text-shadow: none;
}
body.skin-quiet .day-cell.cell-R .day-num,
body.skin-quiet .day-cell.cell-P .day-num,
body.skin-quiet .day-cell.cell-N .day-num {
  color: var(--text-main);
  text-shadow: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.55em;
  min-height: 1.55em;
  border-radius: 50%;
  border: 2px solid transparent;
  box-sizing: border-box;
  line-height: 1;
  padding: 1px;
}
body.skin-quiet .day-cell.cell-R .day-num { border-color: var(--color-R); }
body.skin-quiet .day-cell.cell-P .day-num { border-color: var(--color-P); }
body.skin-quiet .day-cell.cell-N .day-num { border-color: var(--color-N); }

body.skin-quiet .day-cell.urlop {
  background: var(--bg-cell) !important;
  color: var(--text-main) !important;
  border: 1px solid var(--color-U) !important;
  text-shadow: none !important;
}
body.skin-quiet .day-cell.urlop::after {
  display: none !important;
  content: none !important;
}
body.skin-quiet .day-cell.urlop .day-num {
  color: var(--text-main) !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.55em;
  min-height: 1.55em;
  border-radius: 50%;
  border: 2px solid var(--color-U) !important;
  box-sizing: border-box;
  line-height: 1;
  padding: 1px;
}
body.skin-quiet .day-cell.urlop .day-shift {
  color: var(--text-main) !important;
}

