/* === EDIT PALETTE === */
.edit-palette {
  position: fixed;
  bottom: 80px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--bg-container);
  border: 2px solid var(--text-header);
  border-radius: 14px;
  padding: 8px;
  display: none;
  gap: 6px;
  box-shadow: 0 8px 30px var(--shadow-heavy);
  z-index: 25;
  animation: slideUpFade 0.3s ease-out;
}
.edit-palette.show {
  display: flex;
}
@keyframes slideUpFade {
  from {
    opacity: 0;
    transform: translate(-50%, 20px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}
.palette-btn {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  border: 2px solid transparent;
  cursor: pointer;
  font-size: 20px;
  font-weight: bold;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #fff;
  transition: all 0.15s;
  position: relative;
}
.palette-btn:hover {
  transform: scale(1.1);
}
.palette-btn.active {
  border-color: #f1c40f;
  box-shadow: 0 0 0 3px rgba(241, 196, 15, 0.4);
  transform: scale(1.1);
}
.palette-btn.p-R {
  background: var(--color-R);
}
.palette-btn.p-P {
  background: var(--color-P);
}
.palette-btn.p-N {
  background: var(--color-N);
}
.palette-btn.p-W {
  background: var(--color-W);
  color: var(--color-W-text);
}
.palette-btn.p-CYCLE {
  background: linear-gradient(135deg, #6a1b9a, #4a148c);
}
.palette-btn.p-OT {
  background: linear-gradient(135deg, #f1c40f, #d68910);
  color: #1a1a1a;
}
.palette-btn .pb-hotkey {
  position: absolute;
  top: 2px;
  right: 3px;
  font-size: 8px;
  opacity: 0.75;
  background: rgba(0, 0, 0, 0.3);
  padding: 1px 3px;
  border-radius: 3px;
}

/* === EDIT BANNER === */
.edit-banner {
  background: linear-gradient(135deg, #e67e22, #d35400);
  color: #fff;
  padding: 12px 16px;
  border-radius: 12px;
  margin: 10px 0;
  display: none;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
  box-shadow: 0 4px 15px rgba(230, 126, 34, 0.4);
  animation: slideDown 0.3s ease-out;
}
@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-15px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.edit-banner.show {
  display: flex;
}
.edit-banner-text {
  font-weight: 600;
  font-size: 14px;
