}
.day-cell .shift-rate-badge {
  z-index: 5;
}
.day-cell .relief-popup {
  z-index: 28;
}
.day-cell .ot-detail-popup {
  z-index: 30;
}
.day-cell:hover {
  z-index: 35;
}
.day-cell.selected {
  z-index: 36;
}

/* ── 2. Desktop: ensure overflow visible for popups ── */
.day-cell {
  overflow: visible !important;
}

