}
body.theme-dark {
  --bg-body: linear-gradient(135deg, #0a0e27, #1a1a2e);
  --bg-container: #1e222d;
  --text-main: #e0e0e0;
  --text-header: #64b5f6;
  --bg-controls: #2a2e3a;
  --bg-cell: #262a35;
  --border-cell: #3d4250;
  --bg-info: linear-gradient(135deg, #262a35, #1e222d);
