/* === YEAR VIEW === */
.year-view {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-top: 10px;
  max-width: 100%;
  overflow: hidden;
}
.year-month {
  background: var(--bg-cell);
  border-radius: 12px;
  padding: 10px;
  border: 1px solid var(--border-cell);
  cursor: pointer;
  transition: all 0.2s;
  min-width: 0;
  overflow: hidden;
}
.year-month:hover {
  transform: translateY(-3px);
  box-shadow: 0 6px 16px var(--shadow-color);
}
.year-month h4 {
  margin: 0 0 6px;
  text-align: center;
  color: var(--text-header);
  font-size: 14px;
}
.mini-calendar {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
  min-width: 0;
}
.mini-day {
  border-radius: 3px;
  font-size: 9px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255, 255, 255, 0.95);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
  min-width: 0;
  width: 100%;
  height: 18px;
  overflow: hidden;
  transition: transform 0.1s;
  cursor: pointer;
  position: relative;
}
.mini-day:hover {
  transform: scale(1.3);
  z-index: 5;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.4);
}
.mini-day.mR {
  background: var(--color-R);
}
.mini-day.mP {
  background: var(--color-P);
}
.mini-day.mN {
  background: var(--color-N);
}
.mini-day.mW {
  background: var(--color-W);
  color: var(--color-W-text);
  text-shadow: none;
}
.mini-day.mE {
  background: transparent;
  cursor: default;
}
.mini-day.mE:hover {
  transform: none;
  box-shadow: none;
}
.mini-day.mToday {
  outline: 2px solid #f1c40f;
