let popupFadeTimer = null;

/* === HELPER: Safe event binding === */
function bindEvent(id, event, handler) {
  const el = document.getElementById(id);
  if (el) {
    el.addEventListener(event, handler);
  } else {
    console.warn(`[main.js] Element #${id} not found — event "${event}" not bound`);
  }
}

/* === URL PARAMS === */
(function applyUrlParams() {
  const p = new URLSearchParams(window.location.search);
  if (!p.toString()) return; // немає параметрів — виходимо

  // View
  const v = p.get('view');
  if (v && ['dashboard', 'month', 'table'].includes(v)) {
    currentView = v;
    prefs.view = v;
  }

  // Rok mode
  if (p.get('rok') === '1') {
    yearMode = true;
    prefs.yearMode = true;
  }

  // Year
  const y = parseInt(p.get('y'), 10);
  if (y >= MIN_YEAR && y <= MAX_YEAR) {
    currentYear = y;
    prefs.year = y;
  }

  // Month
  const m = parseInt(p.get('m'), 10);
  if (m >= 1 && m <= 12) {
    currentMonth = m;
  }

  // Day
  const d = parseInt(p.get('d'), 10);
  if (d >= 1 && d <= 31) {
    selectedDay = d;
  }

  // Brigade
  const b = (p.get('brig') || '').toUpperCase();
  if (['A', 'B', 'C', 'D'].includes(b)) {
    selectedShift = b;
    prefs.shift = b;
  }

  // Save updated prefs
  savePrefs(prefs);
})();

if (currentYear < MIN_YEAR) currentYear = MIN_YEAR;
if (currentYear > MAX_YEAR) currentYear = MAX_YEAR;

// Clear the URL after loading parameters
if (window.location.search) {
  history.replaceState({}, '', window.location.pathname);
}

/* === VIEW SWITCHER === */
function switchView(view) {
  currentView = view;
  prefs.view = view;
  savePrefs(prefs);
  document
    .querySelectorAll('.view-btn')
    .forEach((b) => b.classList.toggle('active', b.dataset.view === view));
  updateYearToggleState();
  refreshViews();
}

function updateYearToggleState() {
  const lbl = document.getElementById('yearToggleLabel');
  const cb = document.getElementById('yearToggle');
  const isSupported = currentView === 'month' || currentView === 'table';
  if (!isSupported) {
    lbl.classList.add('disabled');
    lbl.classList.remove('active');
    cb.checked = false;
  } else {
    lbl.classList.remove('disabled');
    cb.checked = yearMode;
    lbl.classList.toggle('active', yearMode);
  }
}
document.querySelectorAll('#viewSwitcher .view-btn').forEach((b) => {
  b.onclick = () => switchView(b.dataset.view);
});
bindEvent('yearToggle', 'change', (e) => {
  yearMode = e.target.checked;
  prefs.yearMode = yearMode;
  savePrefs(prefs);
  const label = document.getElementById('yearToggleLabel');
  if (label) label.classList.toggle('active', yearMode);
  refreshViews();
});

window.addEventListener('driveAuthChanged', () => {
  try {
    refreshViews();
  } catch (e) {
    console.warn('[main] refresh after auth', e);
  }
});

function refreshViews() {
  const views = ['dashboardView', 'monthView', 'yearView', 'tableView'];
  views.forEach((v) => (document.getElementById(v).style.display = 'none'));

  updateYearPicker();
  updateEditModeUI();
  updateYearToggleState();

  const empty =
    !hasFactoryData(currentYear) &&
    !hasCustomData(currentYear) &&
    currentView !== 'dashboard' &&
    !editMode;

  // Remove the old overtime summary when switching views
  const oldOtSum = document.getElementById('otMonthSummary');
  if (oldOtSum) oldOtSum.remove();

  if (currentView === 'dashboard') {
    document.getElementById('dashboardView').style.display = 'block';
    renderDashboard();
  } else if (currentView === 'month') {
    if (yearMode) {
      document.getElementById('yearView').style.display = 'grid';
      if (empty) {
        renderEmptyState(document.getElementById('yearView'));
        document.getElementById('yearView').style.display = 'block';
        return;
      }
      renderYearView();
    } else {
      document.getElementById('monthView').style.display = 'block';
      if (empty) {
        document.getElementById('calendar').innerHTML = '';
        renderEmptyState(document.getElementById('calendar'));
        document.getElementById('infoPanel').innerHTML = '';
        document.getElementById('monthTitle').textContent =
          `${monthNames[currentMonth - 1]} ${currentYear}`;
        return;
      }
      renderCalendar();
      renderInfo();
    }
  } else if (currentView === 'table') {
    document.getElementById('tableView').style.display = 'block';
    if (empty) {
      renderEmptyState(document.getElementById('tableView'));
      return;
    }
    renderTableView(yearMode);
  }
}

function updateShiftButtons() {
  document.querySelectorAll('.shift-btn').forEach((b) => {
    b.classList.remove('active');
    b.classList.remove('compare');
    if (b.dataset.shift === selectedShift) b.classList.add('active');
  });
}
function updateYearPicker() {
  document.getElementById('yearCurrent').textContent = currentYear;
  const yp = document.getElementById('yearPicker');
  if (hasFactoryData(currentYear) || hasCustomData(currentYear)) {
    yp.classList.remove('no-data');
    yp.title = hasCustomData(currentYear)
      ? t('yearWithChanges', { year: currentYear })
      : t('yearFactoryData', { year: currentYear });
  } else {
    yp.classList.add('no-data');
    yp.title = t('yearNoData', { year: currentYear });
  }
}
