/* ================================================================
   GRAFIK GILLETTE — Logic module (Overtime)
   Ten plik zawiera czyste funkcje obliczeniowe, bez zależności od DOM/LS.
   
   Requires: js/schedules/_core.js (for shiftHours + buildHolidays)
   ================================================================ */

// In the browser, _core.js is loaded before this file and provides these names
// through the shared classic-script scope. Under Node.js, require the core explicitly.
const overtimeCore =
  typeof module !== 'undefined' && module.exports && typeof require === 'function'
    ? require('./schedules/_core.js')
    : null;

/**
 * Categorizes overtime hours into pay rates (+50%, +100%, +200%).
 * @param {number} year
 * @param {number} month - 1-12
 * @param {number} day - 1-31
 * @param {string} shift - 'R', 'P', 'N'
 * @param {string} position - 'przed', 'po', 'weekend'
 * @param {number} hours
 * @returns {object} - { h50, h100, h200 }
 */
function categorizeOvertime(year, month, day, shift, position, hours) {
  const yHolidays = (overtimeCore ? overtimeCore.buildHolidays : buildHolidays)(year);
  const isHoliday = !!yHolidays[month + '-' + day];
  const dow = new Date(year, month - 1, day).getDay();
  const isSunday = dow === 0;

  // Holiday work — always +200%
  if (isHoliday) return { h50: 0, h100: 0, h200: hours };

  // Weekend overtime (work on a day off/holiday)
  if (position === 'weekend') {
    if (isSunday) return { h50: 0, h100: hours, h200: 0 };
    return { h50: 0, h100: hours, h200: 0 }; // Saturday or dzień wolny — +100%
  }

  const [shStart, shEnd] = (overtimeCore ? overtimeCore.shiftHours : shiftHours)[shift];
  let curHour;
  if (position === 'przed') curHour = shStart - hours;
  else curHour = shEnd;
  if (curHour < 0) curHour += 24;

  let nightH = 0,
    dayH = 0;
  for (let i = 0; i < hours; i++) {
    const h = (((curHour + i) % 24) + 24) % 24;
    if (h >= 22 || h < 6) nightH++;
    else dayH++;
  }
  if (isSunday) return { h50: 0, h100: dayH + nightH, h200: 0 };
  return { h50: dayH, h100: nightH, h200: 0 };
}

/**
 * Calculates start/end time of overtime based on shift and position.
 * @param {string} shift - 'R', 'P', 'N'
 * @param {string} position - 'przed' or 'po'
 * @param {number} hours
 * @returns {object} - { from, to }
 */
function calcOvertimeTime(shift, position, hours) {
  const [start, end] = (overtimeCore ? overtimeCore.shiftHours : shiftHours)[shift];
  let from, to;
  if (position === 'przed') {
    to = start;
    from = start - hours;
    if (from < 0) from += 24;
  } else {
    from = end % 24;
    to = (end + hours) % 24;
  }
  return { from, to };
}

// Node.js export (for tests)
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { categorizeOvertime, calcOvertimeTime };
}

/* ================================================================
   GRAFIK GILLETTE — Settings hub + cell colors + skins
   prefs.cellColors, prefs.cellSkin, prefs.urlopLimits
   ================================================================ */

const DEFAULT_CELL_COLORS = {
  R: '#f1c40f',
  P: '#82e0aa',
  N: '#aed6f1',
  U: '#14b8a6',
};

const CELL_SKINS = ['full', 'strip', 'quiet'];
const DEFAULT_CELL_SKIN = 'full';

const COLOR_PRESETS = [
  '#f1c40f', '#f39c12', '#e67e22', '#e74c3c', '#c0392b',
  '#82e0aa', '#27ae60', '#1abc9c', '#16a085', '#0e6655',
  '#aed6f1', '#5dade2', '#3498db', '#2980b9', '#1a5276',
  '#2dd4bf', '#14b8a6', '#0f766e', '#f9a8d4', '#a78bfa',
  '#8b7a9e', '#7b6b8f', '#94a3b8', '#64748b', '#1e293b',
];

function _hexToRgb(hex) {
  const h = String(hex || '').replace('#', '').trim();
  if (h.length === 3) {
    return {
      r: parseInt(h[0] + h[0], 16),
      g: parseInt(h[1] + h[1], 16),
      b: parseInt(h[2] + h[2], 16),
    };
  }
  if (h.length !== 6) return { r: 128, g: 128, b: 128 };
  return {
    r: parseInt(h.slice(0, 2), 16),
    g: parseInt(h.slice(2, 4), 16),
    b: parseInt(h.slice(4, 6), 16),
  };
}

function _normalizeHex(hex) {
  let h = String(hex || '').trim();
  if (!h.startsWith('#')) h = '#' + h;
  if (/^#[0-9a-fA-F]{3}$/.test(h)) {
    h = '#' + h[1] + h[1] + h[2] + h[2] + h[3] + h[3];
  }
  if (!/^#[0-9a-fA-F]{6}$/.test(h)) return null;
  return h.toLowerCase();
}

function _luminance(hex) {
  const { r, g, b } = _hexToRgb(hex);
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255;
}

function _textOn(hex) {
  return _luminance(hex) > 0.55 ? '#1a1a1a' : '#ffffff';
}

function _darken(hex, factor) {
  const { r, g, b } = _hexToRgb(hex);
  const f = Math.max(0, Math.min(1, factor));
  const d = (c) => Math.round(c * (1 - f));
  return (
    '#' +
    [d(r), d(g), d(b)]
      .map((x) => x.toString(16).padStart(2, '0'))
      .join('')
  );
}

function getCellColors() {
  const c = (prefs && prefs.cellColors) || {};
  return {
    R: _normalizeHex(c.R) || DEFAULT_CELL_COLORS.R,
    P: _normalizeHex(c.P) || DEFAULT_CELL_COLORS.P,
    N: _normalizeHex(c.N) || DEFAULT_CELL_COLORS.N,
    U: _normalizeHex(c.U) || DEFAULT_CELL_COLORS.U,
  };
}

function applyCellColors(colors) {
  const c = colors || getCellColors();
  const root = document.documentElement;
  const set = (k, v) => root.style.setProperty(k, v);

  set('--color-R', c.R);
  set('--color-R-border', _darken(c.R, 0.18));
  set('--color-R-text', _textOn(c.R));

  set('--color-P', c.P);
  set('--color-P-border', _darken(c.P, 0.18));
  set('--color-P-text', _textOn(c.P));

  set('--color-N', c.N);
  set('--color-N-border', _darken(c.N, 0.18));
  set('--color-N-text', _textOn(c.N));
  set('--color-N-grad', `linear-gradient(135deg, ${c.N}, ${_darken(c.N, 0.25)})`);

  set('--color-U', c.U);
  set('--color-U-border', _darken(c.U, 0.2));
  set('--color-U-text', _textOn(c.U));
  set('--color-U-grad', `linear-gradient(135deg, ${c.U}, ${_darken(c.U, 0.28)})`);
}

function saveCellColors(colors, markSync) {
  if (!prefs.cellColors) prefs.cellColors = {};
  ['R', 'P', 'N', 'U'].forEach((k) => {
    const n = _normalizeHex(colors[k]);
    if (n) prefs.cellColors[k] = n;
  });
  savePrefs(prefs, markSync !== false);
  applyCellColors(getCellColors());
}

function resetCellColors() {
  prefs.cellColors = { ...DEFAULT_CELL_COLORS };
  savePrefs(prefs, true);
  applyCellColors(getCellColors());
}

function getCellSkin() {
  const s = prefs && prefs.cellSkin;
  return CELL_SKINS.includes(s) ? s : DEFAULT_CELL_SKIN;
}

function applyCellSkin(skin) {
  const s = CELL_SKINS.includes(skin) ? skin : getCellSkin();
  document.body.classList.remove('skin-full', 'skin-strip', 'skin-quiet');
  document.body.classList.add('skin-' + s);
}

function saveCellSkin(skin, markSync) {
