  name: 'Gillette IV brygady',
  type: 'rotating-4x3',
  description: 'System 4 brygad w cyklu ciaglym 24/7 (R/P/N)',

  // Entity type — what units are scheduled?
  entityLabel: 'Brygada',
  entities: ['A', 'B', 'C', 'D'],

  // Shift types available in this schedule
  shiftTypes: ['R', 'P', 'N'],
  freeShift: '',

